if(!base||base.ppsDiagnosisExpansion20261014)throw Error('Unexpected PPS parents expansion baseline');
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const index=new Map();
for(const t of data.topics)for(const name of [t.key,t.label,...t.aliases]){const n=norm(name);if(base.resolve(name)||index.has(n))throw Error('Topic collision: '+name);index.set(n,t);}
const expectedBaseline=base.topics.map(t=>({key:t.key,json:JSON.stringify(t)}));
const expectedAdditions=data.topics.map(t=>({key:t.key,json:JSON.stringify(t)}));
root.PaisPpsContentManifest20261014=Object.freeze({version:10,keys:Object.freeze(expectedAdditions.map(t=>t.key)),validateExtension(original,count=expectedBaseline.length){const current=root.PaisGuide.topics;if(!Array.isArray(original)||count!==expectedBaseline.length||current.length!==expectedBaseline.length+expectedAdditions.length||new Set(current.map(t=>t.key)).size!==current.length)return false;return expectedAdditions.every(e=>JSON.stringify(current.find(t=>t.key===e.key))===e.json);}});
const sources={...base.sources,...data.sources},topics=[...base.topics,...data.topics].sort((a,b)=>a.label.localeCompare(b.label,'pt-BR'));
function resolve(v){return index.get(norm(v))||base.resolve(v);}
function build(input={}){const p=input&&typeof input==='object'?input:{},t=index.get(norm(p.diagnosis));if(!t)return base.build(p);
 const emergency=p.danger==='yes'||(p.age==='u3m'&&p.fever==='yes');
 const age=p.age||'unknown';if(!Object.hasOwn(base.ages,age))return {ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.'};
 const sections=(t.ageSpecific?.[age]?.sections||t.sections).map(s=>({title:s.title,items:[...s.items]}));
 if(emergency)sections[0].items.unshift(p.danger==='yes'?'Foi informado um sinal de gravidade: procure atendimento imediatamente. As informações abaixo não autorizam esperar em casa.':'Febre em bebê menor de 3 meses exige avaliação imediata, mesmo que pareça bem. As informações abaixo não autorizam esperar em casa.');
 const text='ORIENTAÇÕES AOS PAIS — '+t.label+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>'• '+x).join('\n')).join('\n\n');
 return {ok:true,mode:emergency||t.urgency?'urgent':'guidance',topic:t.key,label:t.label,sections,refs:[...new Set([...t.refs,...(emergency?['fever','samuMS']:[])])],text};
}
const testAge=t=>index.has(norm(t.key))?'u3m':base.testAge(t);
function audit(){const old=base.audit(),issues=[...(old.issues||[])];if(!expectedBaseline.every(e=>JSON.stringify(root.PaisGuide.topics.find(t=>t.key===e.key))===e.json))issues.push('pps20261014-baseline-mutation');for(const t of data.topics){const r=build({diagnosis:t.key});if(!r.ok||r.refs.some(x=>!sources[x])||JSON.stringify(root.PaisGuide.topics.find(x=>x.key===t.key))!==JSON.stringify(t))issues.push('pps20261014:'+t.key);}return {...old,ok:!issues.length,issues,topics:topics.length};}
root.PaisGuide={...base,topics,sources,resolve,build,testAge,audit,coverage:{...base.coverage,totalCards:topics.length,fullPpsCoverageVerified:false},ppsDiagnosisExpansion20261014:{checked:data.checked,added:data.topics.length,fullCoverageVerified:false}};
